385:   private void applyDefaults() {
386:     if (credentialsCachePath == null) {
387:       credentialsCachePath =
388:           Paths.get(System.getProperty("user.home"), ".camunda", "credentials")
389:               .toAbsolutePath()
390:               .toString();
391:     }
392: 
393:     if (authorizationServerUrl == null) {
394:       authorizationServerUrl = DEFAULT_AUTHORIZATION_SERVER_URL;
395:     }
396: 
397:     if (connectTimeout == null) {
398:       connectTimeout = DEFAULT_CONNECT_TIMEOUT;
399:     }
400: 
401:     if (readTimeout == null) {
402:       readTimeout = DEFAULT_READ_TIMEOUT;
403:     }
404:   }
