406:   private void validate() {
407:     try {
408:       Objects.requireNonNull(clientId, String.format(INVALID_ARGUMENT_MSG, "client id"));
409:       if (entraConfigurationProvided()) {
410:         // loading the certificate from the provided path to ensure it exists and is valid
411:         final KeyStore keyStore = KeyStore.getInstance("PKCS12");
412:         keyStore.load(
413:             Files.newInputStream(Paths.get(entraCertificatePath.toAbsolutePath().toString())),
414:             entraCertificatePassword.toCharArray());
415:       } else {
416:         Objects.requireNonNull(clientSecret, String.format(INVALID_ARGUMENT_MSG, "client secret"));
417:       }
418:       Objects.requireNonNull(audience, String.format(INVALID_ARGUMENT_MSG, "audience"));
419:       Objects.requireNonNull(
420:           authorizationServerUrl, String.format(INVALID_ARGUMENT_MSG, "authorization server URL"));
421: 
422:       authorizationServer = new URL(authorizationServerUrl);
423: 
424:       if (keystorePath != null && !keystorePath.toFile().exists()) {
425:         throw new IllegalArgumentException("Keystore path does not exist: " + keystorePath);
426:       }
427: 
428:       if (truststorePath != null && !truststorePath.toFile().exists()) {
429:         throw new IllegalArgumentException("Truststore path does not exist: " + keystorePath);
430:       }
431: 
432:       credentialsCache = new File(credentialsCacheFilePath);
433: 
434:       if (credentialsCache.isDirectory()) {
435:         throw new IllegalArgumentException(
436:             "Expected specified credentials cache to be a file but found directory instead.");
437:       }
438:       validateTimeout(connectTimeout, "ConnectTimeout");
439:       validateTimeout(readTimeout, "ReadTimeout");
440:     } catch (final NullPointerException
441:         | IOException
442:         | KeyStoreException
443:         | NoSuchAlgorithmException
444:         | CertificateException e) {
445:       throw new IllegalArgumentException(e);
446:     }
447:   }
