431: 
432:     final String encodedBody =
433:         map.entrySet().stream()
434:             .map(e -> encode(e.getKey()) + "=" + encode(e.getValue()))
435:             .collect(Collectors.joining("&"));
436: 
437:     map.put("access_token", token);
438:     map.put("token_type", TOKEN_TYPE);
439:     map.put(
440:         "expires_in",
441:         String.valueOf(
442:             EXPIRY.getLong(ChronoField.INSTANT_SECONDS) - Instant.now().getEpochSecond()));
