540:     final List<String> firstSortValues =
541:         result.page().firstSortValues().stream().map(Object::toString).toList();
542:     String creationDateMillis = convertDateIfNeeded(firstSortValues.getFirst());
543:     String userTaskKey = firstSortValues.getLast();
544: 
545:     assertThat(creationDateMillis)
546:         .isEqualTo(
547:             Long.toString(
548:                 OffsetDateTime.parse(firstItem.getCreationDate()).toInstant().toEpochMilli()));
549:     assertThat(userTaskKey).isEqualTo(Long.toString(firstItem.getUserTaskKey()));
550: 
551:     final List<String> lastSortValues =
552:         result.page().lastSortValues().stream().map(Object::toString).toList();
553:     creationDateMillis = convertDateIfNeeded(lastSortValues.getFirst());
554:     userTaskKey = lastSortValues.getLast();
555: 
556:     assertThat(creationDateMillis)
557:         .isEqualTo(
558:             Long.toString(
559:                 OffsetDateTime.parse(lastItem.getCreationDate()).toInstant().toEpochMilli()));
