1437:         .send()
1438:         .join();
1439: 
1440:     camundaClient.newUserTaskCompleteCommand(userTaskKeyTaskAssigned).send().join();
1441: 
1442:     Awaitility.await("should export Assigned task and Completed to ElasticSearch")
1443:         .atMost(TIMEOUT_DATA_AVAILABILITY)
1444:         .ignoreExceptions() // Ignore exceptions and continue retrying
1445:         .untilAsserted(
1446:             () -> {
1447:               final var result =
1448:                   camundaClient
1449:                       .newUserTaskSearchRequest()
1450:                       .filter(f -> f.assignee("demo"))
