34: /**
35:  * This class provides methods to fetch entities for batch operations. It uses the search client
36:  * proxy to access the secondary database.
37:  */
38: public class BatchOperationItemProvider {
39: 
40:   private static final Logger LOG = LoggerFactory.getLogger(BatchOperationItemProvider.class);
41: 
42:   private final SearchClientsProxy searchClientsProxy;
43:   private final BatchOperationMetrics metrics;
44: 
45:   /**
46:    * The size of a page when fetching entities. This is the maximum number of items that can be
47:    * fetched in a single query and is limited by ElasticSearch.
48:    */
49:   private final int queryPageSize;
50: 
51:   /**
52:    * The maximum number of keys that can be passed in a single IN clause in a query. This is limited
53:    * to 1000 because the Oracle DB supports a maximum of 1000 elements in an IN clause.
54:    */
55:   private final int inClauseSize;
56: 
57:   public BatchOperationItemProvider(
58:       final SearchClientsProxy searchClientsProxy,
59:       final EngineConfiguration engineConfiguration,
60:       final BatchOperationMetrics metrics) {
61:     this.searchClientsProxy = searchClientsProxy;
62:     this.metrics = metrics;
63:     queryPageSize = engineConfiguration.getBatchOperationQueryPageSize();
64:     inClauseSize = engineConfiguration.getBatchOperationQueryInClauseSize();
65:   }
66: 
67:   /**
68:    * Fetches the process instance items for the given partitionId based on the provided filter. The
69:    * items are fetched sequentially in pages. Depending on the overall size of the result, this can
70:    * cause multiple queries to the secondary database.
71:    *
72:    * @param filter the filter to use
73:    * @param authentication the authentication to use
74:    * @param shouldAbort if the process should be aborted
75:    * @return a set of all found process instance items
76:    */
77:   public Set<Item> fetchProcessInstanceItems(
78:       final int partitionId,
79:       final ProcessInstanceFilter filter,
80:       final Authentication authentication,
81:       final Supplier<Boolean> shouldAbort) {
82:     final var processInstanceFilter = filter.toBuilder().partitionId(partitionId).build();
83: 
84:     LOG.debug(
85:         "Fetching process instance items for partition {} with filter: {}",
86:         partitionId,
87:         processInstanceFilter);
88: 
89:     return fetchEntityItems(
90:         new ProcessInstancePageFetcher(), processInstanceFilter, authentication, shouldAbort);
91:   }
92: 
93:   /**
94:    * Fetches the incident items based on the provided incident filter. The items are fetched
95:    * sequentially in pages. Depending on the overall size of the result this can cause multiple
96:    * queries to the secondary database.
97:    *
98:    * @param filter the filter to use
99:    * @param authentication the authentication to use
100:    * @param shouldAbort if the process should be aborted
101:    * @return a set of all found process instance items
102:    */
103:   public Set<Item> fetchIncidentItems(
104:       final IncidentFilter filter,
105:       final Authentication authentication,
106:       final Supplier<Boolean> shouldAbort) {
107: 
108:     LOG.debug("Fetching incident items with filter: {}", filter);
109:     return fetchEntityItems(new IncidentPageFetcher(), filter, authentication, shouldAbort);
110:   }
111: 
112:   /**
113:    * Fetches the incident items based on the provided process instance filter for the given
114:    * partitonId. This will return <b>ALL</b> incidents of the matching processInstances. The items
115:    * are fetched sequentially in pages. Depending on the overall size of the result, this can cause
116:    * multiple queries to the secondary database.
117:    *
118:    * @param filter the filter to use
119:    * @param authentication the authentication to use
120:    * @param shouldAbort if the process should be aborted
121:    * @return a set of all found incident items
122:    */
123:   public Set<Item> fetchIncidentItems(
124:       final int partitionId,
125:       final ProcessInstanceFilter filter,
126:       final Authentication authentication,
127:       final Supplier<Boolean> shouldAbort) {
128:     // first fetch all matching processInstances
129:     final var processInstanceKeys =
130:         fetchProcessInstanceItems(partitionId, filter, authentication, shouldAbort).stream()
131:             .map(Item::processInstanceKey)
132:             .toList();
133: 
134:     // then fetch all incidents of the matching processInstances
135:     return getIncidentItemsOfProcessInstanceKeys(
136:         new ArrayList<>(processInstanceKeys), authentication, shouldAbort);
137:   }
