171:   private Set<Item> getIncidentItemsOfProcessInstanceKeys(
172:       final List<Long> processInstanceKeys,
173:       final Authentication authentication,
174:       final Supplier<Boolean> shouldAbort) {
175:     final Set<Item> incidents = new LinkedHashSet<>();
176: 
177:     final List<List<Long>> processInstanceKeysBatches =
178:         Lists.partition(processInstanceKeys, inClauseSize);
179: 
180:     for (final List<Long> processInstanceKeysBatch : processInstanceKeysBatches) {
181:       if (shouldAbort.get()) {
182:         return Set.of();
183:       }
184:       final var filter =
185:           new IncidentFilter.Builder()
186:               .processInstanceKeyOperations(
187:                   FilterUtil.mapDefaultToOperation(processInstanceKeysBatch))
188:               .build();
189:       incidents.addAll(fetchIncidentItems(filter, authentication, shouldAbort));
190:     }
191: 
192:     return incidents;
193:   }
